  const initPoint = (pointConfig, obj, group, name, config) => {
    const { sitnum1, sitnum2, sitInterp, sitInterp1, sitOrder, oriOrder } = config
    const { position, rotation, scale, } = pointConfig

    // const AMOUNTX = sitnum1 * sitInterp + sitOrder * 2;
    // const AMOUNTY = sitnum2 * sitInterp1 + sitOrder * 2;
    // const numParticles = AMOUNTX * AMOUNTY;
    const numParticles = obj.length
    const positions = new Float32Array(numParticles * 3);
    const scales = new Float32Array(numParticles);
    const colors = new Float32Array(numParticles * 3);

    let i = 0,
      j = 0;

    // for (let ix = 0; ix < AMOUNTX; ix++) {
    //   for (let iy = 0; iy < AMOUNTY; iy++) {
    //     positions[i] = iy * SEPARATION - (AMOUNTX * SEPARATION) / 2; // x
    //     positions[i + 1] = 0; // y
    //     positions[i + 2] = ix * SEPARATION - (AMOUNTY * SEPARATION) / 2; // z

    //     scales[j] = 1;
    //     colors[i] = 0 / 255;
    //     colors[i + 1] = 0 / 255;
    //     colors[i + 2] = 255 / 255;
    //     i += 3;
    //     j++;
    //   }
    // }

    const backObj = obj

    const height = (sitnum1 + oriOrder * 2) * sitInterp
    const width = (sitnum2 + oriOrder * 2) * sitInterp1
    // for (let ix = 0; ix < backObj.length; ix++) {
    for (let a = 0; a < height; a++) {
      for (let b = 0; b < width; b++) {

        const ix = a * width + b
        positions[i] = backObj[ix].X * 20 - 3000; // x
        positions[i + 1] = 0; // y
        positions[i + 2] = backObj[ix].Y * 20 - 3000; // z

        if (name == 'sit') {
          positions[i + 1] = 100 * Math.sin(a * Math.PI / (width));

        }

        scales[j] = 1;
        colors[i] = 0 / 255;
        colors[i + 1] = 0 / 255;
        colors[i + 2] = 255 / 255;
        i += 3;
        j++;
      }
    }

    const sitGeometry = new THREE.BufferGeometry();
    sitGeometry.setAttribute(
      "position",
      new THREE.BufferAttribute(positions, 3)
    );
    function getTexture() {
      return new TextureLoader().load("");
    }
    // require("../../assets/images/circle.png")
    const spite = new THREE.TextureLoader().load("./circle.png");
    const hand = new THREE.TextureLoader().load("./hand.jpg");
    const material = new THREE.PointsMaterial({
      vertexColors: true,
      transparent: true,
      map: spite,
      size: scale[0] * 250,
      // 压力点是「贴在座椅上的覆盖层」，不能和椅子网格比深度。
      // 0717.fbx 是一个不透明闭合网格，而 transparent:true 的材质在 three 里排在
      // 不透明物体之后渲染 —— 椅子先写完深度，点再来做深度测试，全部被判在表面之内丢掉，
      // 于是椅子照常显示、点一个都看不到。关掉深度测试并抬高 renderOrder 才能盖在椅子上。
      // 代价：从背面看时坐垫的点会透过靠背显示出来。覆盖层都是这个取舍。
      depthTest: false,
      depthWrite: false,
    });
    sitGeometry.setAttribute("scale", new THREE.BufferAttribute(scales, 1));
    sitGeometry.setAttribute("color", new THREE.BufferAttribute(colors, 3));
    const particles = new THREE.Points(sitGeometry, material);
    particles.renderOrder = 1;

    // 必须关掉视锥剔除，否则这团点永远画不出来。
    //
    // three 的 Frustum.intersectsObject 只在 geometry.boundingSphere === null 时算一次，
    // 而 setAttribute 不会把 boundingSphere 置空 —— 也就是说包围球只在首帧算，之后再不更新。
    // render() 的顺序是「先 sitRenew 换掉 position 属性，再 renderer.render()」，
    // 所以算包围球时读到的是 sitRenew 刚写的那个缓冲；而 computeBoundingSphere() 读整个
    // attribute，不看 drawRange。启动瞬间座椅上没人，visibleCount 是 0、缓冲全是 0，
    // 算出来就是「局部原点、半径 0」的退化球。这个点被 particles.position
    // （sit 是 -386.5, 303.1, -85）挪到画面外侧，从此每帧都判定不在视锥里。
    //
    // 这团点本来就一直在画面中央，剔除没有任何收益；每帧重算包围球反而要多扫 5184 个点，
    // 而且缓冲尾部的 0 填充会把球撑到原点，算出来也是错的。直接关掉。
    particles.frustumCulled = false;

    particles.scale.x = scale[0];
    particles.scale.y = scale[1];
    particles.scale.z = scale[2];

    // particles.position.z = 0
    // particles.position.y = 0
    // particles.position.x = 0
    if (position.length) particles.position.set(...position)
    if (rotation.length) particles.rotation.set(...rotation)
    particles.name = name
    group.add(particles);
  }

