  function onWindowResize() {
    renderer.setSize(window.innerWidth, window.innerHeight);

    camera.aspect = window.innerWidth / window.innerHeight;

    // camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
  }

  //模型动画

  function animate(timestamp) {

    const delta = timestamp - lastRender;

    if (delta >= 1000 / 40) {
      render();
      lastRender = timestamp;
    }

    // dataFlag = false
    // }
    animationRequestId = requestAnimationFrame(animate);
  }

  function move(position, time, particles) {
    const p1 = {
      x: particles.position.x,
      y: particles.position.y,
      z: particles.position.z,
      rotationx: particles.rotation.x,
      rotationy: particles.rotation.y,
      rotationz: particles.rotation.z,
    };

    const tween1 = new TWEEN.Tween(p1)
      .to(position, time)
      .easing(TWEEN.Easing.Quadratic.InOut);

    tween1.onUpdate(() => {
      particles.position.set(p1.x, p1.y, p1.z);
      if (p1.rotationx) particles.rotation.x = p1.rotationx;
      if (p1.rotationz) particles.rotation.z = p1.rotationz;
    });

    return tween1;
  }

  function actionSit() {

    console.log('sit')
    controls.dynamicDampingFactor = 1;
    particles.visible = true;
    controls.reset()
    const tweena = move(
      {
        x: 0,
        y: 170,
        z: 220,
        rotationx: Math.PI / 3,
        rotationz: 0
      },
      1000,
      particles
    );

    tweena.start();
    // controlsFlag = false;
    particles1.visible = false;
    chair.visible = false;
    particlesHead.visible = false
  }

  function actionBack() {
    controls.dynamicDampingFactor = 1;
    particles1.visible = true;
    controls.reset()
    const tweena = move(
      {
        x: 2,
        y: 165,
        z: 225,
        rotationx: -Math.PI / 2 - (Math.PI * 4.5) / 24,
        rotationz: 0
      },
      1000,
      particles1
    );

    tweena.start();

    // controlsFlag = false; 
    particles.visible = false;
    chair.visible = false;
    particlesHead.visible = false
  }

  function actionHead() {
    controls.dynamicDampingFactor = 1;
    particlesHead.visible = true;
    controls.reset()
    const tweena = move(
      {
        x: 18,
        y: 190,
        z: 250,
        rotationx: -Math.PI / 2 - (Math.PI * 4.5) / 24,
        rotationz: 0
      },
      1000,
      particlesHead
    );

    tweena.start();

    // controlsFlag = false; 
    particles.visible = false;
    chair.visible = false;
    particles1.visible = false
  }


  function actionAll() {
    controls.dynamicDampingFactor = 0.1;
    particles1.visible = true;
    particles.visible = true;
    chair.visible = true;
    particlesHead.visible = true
    // controlsFlag = true;

    controls.reset()


    if (particles.position.z == 220) {
      const tweena = move(
        {
          x: sitX,
          y: sitY,
          z: sitZ,
          rotationx: -Math.PI / 48,
          rotationz: 0
        },
        1000,
        particles
      );

      tweena.start();
    }

    if (particles1.position.z == 225) {
      const tweena = move(
        {
          x: backX,
          y: backY,
          z: backZ,
          rotationx: backRotationX,
          rotationz: 0
        },
        1000,
        particles1
      );

      tweena.start();
    }

    // particlesHead.position.z = backZ;
    // particlesHead.position.y = backY + 52;
    // particlesHead.position.x = backX+15;
    // particlesHead.rotation.x = backRotationX;

    if (particlesHead.position.z == 250) {
      const tweena = move(
        {
          x: backX + 15,
          y: backY + 52,
          z: backZ,
          rotationx: backRotationX,
          rotationz: 0
        },
        1000,
        particlesHead
      );

      tweena.start();
    }
    console.log('actionAll')
  }

